import 'package:flutter/material.dart';import '../theme/operon_theme.dart';import '../widgets/common.dart';
class NotesScreen extends StatefulWidget{const NotesScreen({super.key});@override State<NotesScreen> createState()=>_NotesScreenState();}
class _NotesScreenState extends State<NotesScreen>{final notes=<Map<String,String>>[][];
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Notes')),body:notes.isEmpty?const Center(child:Text('No notes yet')):ListView(children:notes.map((n)=>Card(margin:const EdgeInsets.all(12),child:ListTile(title:Text(n['title']!),subtitle:Text(n['body']!)))).toList()),floatingActionButton:FloatingActionButton(onPressed:()=>_add(c),child:const Icon(Icons.add)));
void _add(BuildContext c){final t=TextEditingController(),b=TextEditingController();showModalBottomSheet(context:c,isScrollControlled:true,showDragHandle:true,builder:(x)=>Padding(padding:EdgeInsets.fromLTRB(20,0,20,MediaQuery.viewInsetsOf(x).bottom+30),child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:t,decoration:const InputDecoration(hintText:'Title')),const SizedBox(height:10),TextField(controller:b,maxLines:5,decoration:const InputDecoration(hintText:'Operator note')),const SizedBox(height:12),FilledButton(onPressed:(){setState(()=>notes.insert(0,{'title':t.text.isEmpty?'Note':t.text,'body':b.text}));Navigator.pop(x);},child:const Text('Save note'))])));}}
